import ApiError from './ApiError.js';
import AuthSession from './AuthSession.js';
import LoginModalEvents from './LoginModalEvents.js';
import PermissionEvents from './PermissionEvents.js';

const REFRESH_PATH = '/auth/refresh.json';
const FALLBACK_ERROR_MESSAGE = 'Request failed';

/**
 * Parse a response's JSON body, without attempting to parse an empty body (e.g. a
 * `204 No Content` response, as returned by `DELETE /auth/logoff.json`) — `response.json()`
 * throws a `SyntaxError` on an empty string, since it is not valid JSON. A non-JSON body
 * (e.g. an HTML error page generated by the proxy) is also treated as `{}`, so error handling
 * can fall back to a generic message instead of crashing on the parse.
 *
 * @param {Response} response - The raw `fetch` response.
 * @returns {Promise<object>} The parsed JSON body, or `{}` when the response has no JSON body.
 */
async function parseBody(response) {
  if (response.status === 204) {
    return {};
  }

  const text = await response.text();

  return text === '' ? {} : parseJson(text);
}

/**
 * Parse a JSON string, tolerating invalid JSON.
 *
 * @param {string} text - The raw response body.
 * @returns {object} The parsed value, or `{}` when `text` is not valid JSON.
 */
function parseJson(text) {
  try {
    return JSON.parse(text);
  } catch {
    return {};
  }
}

/**
 * Build the {@link ApiError} for a failed response.
 *
 * @description Reads the backend's standard error body
 * (`{ error: { code, message, details? }, statusCode, timestamp }`). Falls back to the
 * response's `statusText`, then to a generic message, when the body carries no
 * `error.message` (e.g. a proxy-generated or empty error response), so the resulting error's
 * `message` is never `undefined`.
 * @param {Response} response - The raw `fetch` response.
 * @param {object} data - The parsed response body.
 * @returns {ApiError} The error to throw.
 */
function buildApiError(response, data) {
  const error = data?.error ?? {};
  const message = error.message || response.statusText || FALLBACK_ERROR_MESSAGE;

  return new ApiError(response.status, message, error.code, error.details);
}

/**
 * Perform a raw JSON request, without any `401`-recovery behavior.
 *
 * @description A request without a body (`body === undefined`, e.g. a GET — `fetch` rejects a
 * GET carrying a body) is sent with no `body` option at all.
 * @param {string} method - HTTP method.
 * @param {string} path - Request path.
 * @param {object} [body] - Fields to serialize as the JSON request body; omitted for none.
 * @returns {Promise<{response: Response, data: object}>} The raw response and its parsed
 *   JSON body.
 */
async function request(method, path, body) {
  const options = {
    method,
    credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
  };

  if (body !== undefined) {
    options.body = JSON.stringify(body);
  }

  const response = await fetch(path, options);

  const data = await parseBody(response);

  return { response, data };
}

/**
 * End the client-side session and reject: clear the stored refresh token and open the login
 * modal in Password mode via the shared {@link LoginModalEvents} bus — a pure client-side state
 * transition, with no API call of its own. The modal opening is SSR/spec-safe — skipped when
 * `window` is not defined, the same way the shared `redirectHome` helper guards it.
 *
 * @description The given error is marked with `sessionExpired = true` (see
 * {@link isSessionExpired}) and then thrown, so callers can tell a session expiry (which they
 * must not display) apart from a real failure.
 * @param {ApiError} error - The `ApiError` built from the original `401` response.
 * @returns {never} Never returns; always throws `error`.
 * @throws {ApiError} The given error, marked as `sessionExpired`.
 */
function sessionExpired(error) {
  AuthSession.clear();

  if (typeof window !== 'undefined') {
    LoginModalEvents.open('password');
  }

  error.sessionExpired = true;

  throw error;
}

/**
 * Submit a JSON request, always sending same-origin credentials so the session cookie set
 * by the backend (via `Set-Cookie`) is stored/sent automatically. On a `401`, delegates to
 * {@link handleUnauthorized} unless this is already a retried request, in which case the
 * session is treated as expired directly; with `skipAuthRecovery` a `401` is instead thrown as
 * a plain {@link ApiError}, with no refresh and no session change. On a `403`, announces it on
 * the shared {@link PermissionEvents} bus (so the caller's role is refreshed) before throwing.
 *
 * @param {string} method - HTTP method.
 * @param {string} path - Request path.
 * @param {object} body - Fields to serialize as the JSON request body.
 * @param {object} [options] - Internal call options.
 * @param {boolean} [options.skipAuthRecovery] - Whether a `401` must be thrown as-is, without
 *   attempting a refresh (for `@Public()` routes, where a `401` is a real credential error).
 * @param {boolean} [options.isRetry] - Whether this call is already a post-refresh retry.
 * @param {ApiError} [options.originalError] - The `ApiError` of the first `401`, carried over
 *   to a retry so a failed recovery rejects with it.
 * @returns {Promise<object>} The parsed JSON response body, on success.
 * @throws {ApiError} On any failed response, including an expired session (see
 *   {@link isSessionExpired}).
 */
async function sendJson(method, path, body, { skipAuthRecovery = false, isRetry = false, originalError } = {}) {
  const { response, data } = await request(method, path, body);

  if (response.ok) {
    return data;
  }

  if (response.status === 401 && !skipAuthRecovery) {
    const error = originalError ?? buildApiError(response, data);

    return isRetry
      ? sessionExpired(error)
      : handleUnauthorized(method, path, body, error);
  }

  if (response.status === 403) {
    PermissionEvents.emitForbidden();
  }

  throw buildApiError(response, data);
}

/**
 * Recover from a `401` on the original request: refresh the access token using the stored
 * refresh token and retry the original request once. Falls back to session-expired handling
 * when there is no stored refresh token, or when the refresh call itself fails.
 *
 * @param {string} method - Original request's HTTP method.
 * @param {string} path - Original request's path.
 * @param {object} body - Original request's JSON body.
 * @param {ApiError} originalError - The `ApiError` built from the original `401` response.
 * @returns {Promise<object>} The retried request's parsed JSON body, on success.
 * @throws {ApiError} `originalError`, marked as `sessionExpired`, when the session turned out
 *   to be expired.
 */
async function handleUnauthorized(method, path, body, originalError) {
  const refreshToken = AuthSession.get();

  if (!refreshToken) {
    return sessionExpired(originalError);
  }

  const refreshResponse = await request('POST', REFRESH_PATH, { refreshToken });

  if (!refreshResponse.response.ok) {
    return sessionExpired(originalError);
  }

  AuthSession.set(refreshResponse.data.refreshToken);

  return sendJson(method, path, body, { isRetry: true, originalError });
}

/**
 * Generic JSON HTTP client used by resource-specific clients. Transparently recovers from an
 * expired access token: on a `401`, it refreshes the session once (via the stored refresh
 * token) and retries the original request; if there is no refresh token to use, or the
 * refresh itself fails, the session is cleared, the login modal is opened and the call rejects
 * with the original `401`'s {@link ApiError}, marked as `sessionExpired`. Every method accepts
 * a trailing `{ skipAuthRecovery: true }` option, which turns that recovery off so a `401` is
 * thrown as a plain {@link ApiError} (used for `@Public()` routes).
 */
const ApiClient = {
  /**
   * Submit a GET request, without a body. Same headers/credentials/error-handling shape as
   * {@link ApiClient.postJson}.
   *
   * @param {string} path - Request path.
   * @param {{skipAuthRecovery?: boolean}} [options] - Call options; `skipAuthRecovery` disables
   *   the `401` refresh-and-retry recovery (default `false`).
   * @returns {Promise<object>} The parsed JSON response body, on success.
   * @throws {ApiError} On a failed response, including an expired session.
   */
  async getJson(path, options) {
    return sendJson('GET', path, undefined, options);
  },

  /**
   * Submit a POST request with a JSON body. Always sends same-origin credentials so the
   * session cookie set by the backend (via `Set-Cookie`) is stored/sent automatically.
   *
   * @param {string} path - Request path.
   * @param {object} body - Fields to serialize as the JSON request body.
   * @param {{skipAuthRecovery?: boolean}} [options] - Call options; `skipAuthRecovery` disables
   *   the `401` refresh-and-retry recovery (default `false`).
   * @returns {Promise<object>} The parsed JSON response body, on success.
   * @throws {ApiError} On a failed response, including an expired session.
   */
  async postJson(path, body, options) {
    return sendJson('POST', path, body, options);
  },

  /**
   * Submit a DELETE request with a JSON body. Same headers/credentials/error-handling shape
   * as {@link ApiClient.postJson}.
   *
   * @param {string} path - Request path.
   * @param {object} body - Fields to serialize as the JSON request body.
   * @param {{skipAuthRecovery?: boolean}} [options] - Call options; `skipAuthRecovery` disables
   *   the `401` refresh-and-retry recovery (default `false`).
   * @returns {Promise<object>} The parsed JSON response body, on success.
   * @throws {ApiError} On a failed response, including an expired session.
   */
  async deleteJson(path, body, options) {
    return sendJson('DELETE', path, body, options);
  },

  /**
   * Submit a PATCH request with a JSON body. Same headers/credentials/error-handling shape
   * as {@link ApiClient.postJson}.
   *
   * @param {string} path - Request path.
   * @param {object} body - Fields to serialize as the JSON request body.
   * @param {{skipAuthRecovery?: boolean}} [options] - Call options; `skipAuthRecovery` disables
   *   the `401` refresh-and-retry recovery (default `false`).
   * @returns {Promise<object>} The parsed JSON response body, on success.
   * @throws {ApiError} On a failed response, including an expired session.
   */
  async patchJson(path, body, options) {
    return sendJson('PATCH', path, body, options);
  },
};

export default ApiClient;
